before:
Here is a complete success example without a network request.
```javascript
let state = { status: "idle" };
async function load(getData) {
  state = { status: "loading" };
  try {
    const data = await getData();
    state = { status: "success", data };
  } catch (error) {
    state = { status: "error", message: error.message };
  }
}
async function demo() {
  await load(() => Promise.resolve({ title: "Moon Notes" }));
  console.log(state.status, state.data.title);
}
demo();
```
It eventually prints `success Moon Notes`. The arrow function returns a fulfilled practice Promise. Await inside demo ensures the result is ready before its final display.

